window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0cd97b05a5f0e112"]={"versions": [{"id": "FIG-0cd97b05a5f0e112", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Blockschaltbild eines Subsystems innerhalb des Modells <code>AUTOSAR_sensor_actuator_example/sensor actu...</code>. Im AUTOSAR-Simulink-Entwicklungskontext illustriert das Diagramm die Modellierung interner Sensordynamiken (Filterung und Abtastung/Halteglieder) zwischen durchgeschleiften Eingangssignalen und den zugehörigen AUTOSAR-P-Ports einer Sensor-Software-Komponente bzw. Sensor-Aktuator-Subsystems.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst drei parallele Signalpfade mit folgenden Blöcken und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li>Eingangsebene (Inport-Blöcke):</li>\n<li><code>P-Port1_passthru</code> (Portnummer 1)</li>\n<li><code>P-Port2_passthru</code> (Portnummer 2)</li>\n<li><code>P-Port3_passthru</code> (Portnummer 3)</li>\n<li>Verarbeitungsblöcke (Dynamik / Diskrete Operationen):</li>\n<li><code>Discrete Filter</code> mit der diskreten Übertragungsfunktion $\\frac{1}{1 + 0.5z^{-1}}$</li>\n<li><code>Zero-Order Hold</code> (Abtast-Halte-Glied)</li>\n<li><code>Zero-Order Hold1</code> (weiteres Abtast-Halte-Glied)</li>\n<li>Ausgangsebene (Outport-Blöcke / AUTOSAR-Port-Repräsentationen):</li>\n<li><code>P-Port1</code> (Portnummer 1)</li>\n<li><code>P-Port2</code> (Portnummer 2)</li>\n<li><code>P-Port3</code> (Portnummer 3)</li>\n</ul>\n<p class=\"fig-p\">Die Signalverbindungen verbinden jeweils paarweise einen Inport über das zugehörige Dynamikglied direkt mit dem entsprechenden Outport.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Diskrete Signalverarbeitung im Vorwärtsfluss ohne Rückkopplung:</p>\n<ol class=\"fig-list\">\n<li>Signal an <code>P-Port1_passthru</code> wird im Block <code>Discrete Filter</code> mit einer Verzögerungs- bzw. Tiefpasscharakteristik erster Ordnung rekursiv gefiltert und an <code>P-Port1</code> ausgegeben.</li>\n<li>Signal an <code>P-Port2_passthru</code> wird über den Block <code>Zero-Order Hold</code> zeitdiskret abgetastet und bis zum nächsten Abtastschritt gehalten, bevor es an <code>P-Port2</code> weitergeleitet wird.</li>\n<li>Signal an <code>P-Port3_passthru</code> durchläuft analog den Block <code>Zero-Order Hold1</code> und wird an <code>P-Port3</code> bereitgestellt.</li>\n</ol>\n<p class=\"fig-p\">Die Simulationseinstellungen weisen unten links auf feste Schrittweite (<code>F 98%</code>) und den Solver <code>ode3</code> (Bogacki-Shampine) hin.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient im Simulink-Styleguide als Entwurfsmuster für die Entkopplung und Modellierung physikalischer bzw. zeitlicher Sensordynamiken vor der Übergabe an AUTOSAR-Ports. Entwickler müssen sicherstellen, dass die Abtastzeiten (Sample Times) der Blöcke <code>Discrete Filter</code> und <code>Zero-Order Hold</code> konsistent mit den Perioden der zugehörigen AUTOSAR-Runnables bzw. Task-Aktivierungszeiten im RTE-Kontext parametriert werden. Die Nomenklatur <code>P-PortX_passthru</code> zu <code>P-PortX</code> markiert den modellinternen Übergang von Roh-/Durchgangswerten zu bereitgestellten Schnittstellensignalen.</p>"}, {"id": "FIG-65c1402467929ba6", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Blockschaltbild eines Subsystems innerhalb des Modells <code>AUTOSAR_sensor_actuator_example/sensor actu...</code>. Im AUTOSAR-Simulink-Entwicklungskontext illustriert das Diagramm die Modellierung interner Sensordynamiken (Filterung und Abtastung/Halteglieder) zwischen durchgeschleiften Eingangssignalen und den zugehörigen AUTOSAR-P-Ports einer Sensor-Software-Komponente bzw. Sensor-Aktuator-Subsystems.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst drei parallele Signalpfade mit folgenden Blöcken und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li>Eingangsebene (Inport-Blöcke):</li>\n<li><code>P-Port1_passthru</code> (Portnummer 1)</li>\n<li><code>P-Port2_passthru</code> (Portnummer 2)</li>\n<li><code>P-Port3_passthru</code> (Portnummer 3)</li>\n<li>Verarbeitungsblöcke (Dynamik / Diskrete Operationen):</li>\n<li><code>Discrete Filter</code> mit der diskreten Übertragungsfunktion $\\frac{1}{1 + 0.5z^{-1}}$</li>\n<li><code>Zero-Order Hold</code> (Abtast-Halte-Glied)</li>\n<li><code>Zero-Order Hold1</code> (weiteres Abtast-Halte-Glied)</li>\n<li>Ausgangsebene (Outport-Blöcke / AUTOSAR-Port-Repräsentationen):</li>\n<li><code>P-Port1</code> (Portnummer 1)</li>\n<li><code>P-Port2</code> (Portnummer 2)</li>\n<li><code>P-Port3</code> (Portnummer 3)</li>\n</ul>\n<p class=\"fig-p\">Die Signalverbindungen verbinden jeweils paarweise einen Inport über das zugehörige Dynamikglied direkt mit dem entsprechenden Outport.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Diskrete Signalverarbeitung im Vorwärtsfluss ohne Rückkopplung:</p>\n<ol class=\"fig-list\">\n<li>Signal an <code>P-Port1_passthru</code> wird im Block <code>Discrete Filter</code> mit einer Verzögerungs- bzw. Tiefpasscharakteristik erster Ordnung rekursiv gefiltert und an <code>P-Port1</code> ausgegeben.</li>\n<li>Signal an <code>P-Port2_passthru</code> wird über den Block <code>Zero-Order Hold</code> zeitdiskret abgetastet und bis zum nächsten Abtastschritt gehalten, bevor es an <code>P-Port2</code> weitergeleitet wird.</li>\n<li>Signal an <code>P-Port3_passthru</code> durchläuft analog den Block <code>Zero-Order Hold1</code> und wird an <code>P-Port3</code> bereitgestellt.</li>\n</ol>\n<p class=\"fig-p\">Die Simulationseinstellungen weisen unten links auf feste Schrittweite (<code>F 98%</code>) und den Solver <code>ode3</code> (Bogacki-Shampine) hin.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient im Simulink-Styleguide als Entwurfsmuster für die Entkopplung und Modellierung physikalischer bzw. zeitlicher Sensordynamiken vor der Übergabe an AUTOSAR-Ports. Entwickler müssen sicherstellen, dass die Abtastzeiten (Sample Times) der Blöcke <code>Discrete Filter</code> und <code>Zero-Order Hold</code> konsistent mit den Perioden der zugehörigen AUTOSAR-Runnables bzw. Task-Aktivierungszeiten im RTE-Kontext parametriert werden. Die Nomenklatur <code>P-PortX_passthru</code> zu <code>P-PortX</code> markiert den modellinternen Übergang von Roh-/Durchgangswerten zu bereitgestellten Schnittstellensignalen.</p>"}, {"id": "FIG-1bacfe44be816e2f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Blockschaltbild eines Subsystems innerhalb des Modells <code>AUTOSAR_sensor_actuator_example/sensor actu...</code>. Im AUTOSAR-Simulink-Entwicklungskontext illustriert das Diagramm die Modellierung interner Sensordynamiken (Filterung und Abtastung/Halteglieder) zwischen durchgeschleiften Eingangssignalen und den zugehörigen AUTOSAR-P-Ports einer Sensor-Software-Komponente bzw. Sensor-Aktuator-Subsystems.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst drei parallele Signalpfade mit folgenden Blöcken und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li>Eingangsebene (Inport-Blöcke):</li>\n<li><code>P-Port1_passthru</code> (Portnummer 1)</li>\n<li><code>P-Port2_passthru</code> (Portnummer 2)</li>\n<li><code>P-Port3_passthru</code> (Portnummer 3)</li>\n<li>Verarbeitungsblöcke (Dynamik / Diskrete Operationen):</li>\n<li><code>Discrete Filter</code> mit der diskreten Übertragungsfunktion $\\frac{1}{1 + 0.5z^{-1}}$</li>\n<li><code>Zero-Order Hold</code> (Abtast-Halte-Glied)</li>\n<li><code>Zero-Order Hold1</code> (weiteres Abtast-Halte-Glied)</li>\n<li>Ausgangsebene (Outport-Blöcke / AUTOSAR-Port-Repräsentationen):</li>\n<li><code>P-Port1</code> (Portnummer 1)</li>\n<li><code>P-Port2</code> (Portnummer 2)</li>\n<li><code>P-Port3</code> (Portnummer 3)</li>\n</ul>\n<p class=\"fig-p\">Die Signalverbindungen verbinden jeweils paarweise einen Inport über das zugehörige Dynamikglied direkt mit dem entsprechenden Outport.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Diskrete Signalverarbeitung im Vorwärtsfluss ohne Rückkopplung:</p>\n<ol class=\"fig-list\">\n<li>Signal an <code>P-Port1_passthru</code> wird im Block <code>Discrete Filter</code> mit einer Verzögerungs- bzw. Tiefpasscharakteristik erster Ordnung rekursiv gefiltert und an <code>P-Port1</code> ausgegeben.</li>\n<li>Signal an <code>P-Port2_passthru</code> wird über den Block <code>Zero-Order Hold</code> zeitdiskret abgetastet und bis zum nächsten Abtastschritt gehalten, bevor es an <code>P-Port2</code> weitergeleitet wird.</li>\n<li>Signal an <code>P-Port3_passthru</code> durchläuft analog den Block <code>Zero-Order Hold1</code> und wird an <code>P-Port3</code> bereitgestellt.</li>\n</ol>\n<p class=\"fig-p\">Die Simulationseinstellungen weisen unten links auf feste Schrittweite (<code>F 98%</code>) und den Solver <code>ode3</code> (Bogacki-Shampine) hin.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient im Simulink-Styleguide als Entwurfsmuster für die Entkopplung und Modellierung physikalischer bzw. zeitlicher Sensordynamiken vor der Übergabe an AUTOSAR-Ports. Entwickler müssen sicherstellen, dass die Abtastzeiten (Sample Times) der Blöcke <code>Discrete Filter</code> und <code>Zero-Order Hold</code> konsistent mit den Perioden der zugehörigen AUTOSAR-Runnables bzw. Task-Aktivierungszeiten im RTE-Kontext parametriert werden. Die Nomenklatur <code>P-PortX_passthru</code> zu <code>P-PortX</code> markiert den modellinternen Übergang von Roh-/Durchgangswerten zu bereitgestellten Schnittstellensignalen.</p>"}], "trans": [{"from": "FIG-0cd97b05a5f0e112", "to": "FIG-65c1402467929ba6", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-65c1402467929ba6", "to": "FIG-1bacfe44be816e2f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
